/* From Uiverse.io by Yaseen549 - Tags: button */
.__UIV_SCOPE__ .button {
 color: #ecf0f1;
 font-size: 17px;
 background-color: #212121;
 border: 1px solid #ffffff;
 border-radius: 5px;
 padding: 10px;
 box-shadow: 0px 6px 0px #787878;
 transition: all 50ms;
 width: 120px;
}

.__UIV_SCOPE__ .button:active {
 box-shadow: 0px 2px 0px #787878;
 position: relative;
 top: 2px;
}
